pattern.code-example:
from src.dto.common_dto import ErrorResponse
@router.post( "/instances", response_model=CreateInstanceResponse[ReheatParameters], responses={ 200: {"description": "Instance created with default parameters"}, 500: {"description": "Internal server error", "model": ErrorResponse}, }, ) async def create_instance(): """Create a new VAV Reheat control sequence instance.
Creates an FMU instance with default G36 parameters. The FMU is lazily instantiated on the first step() call. Returns auto-generated instance_id. """

@router.get(
    "/instances/{instance_id}",
    response_model=GetInstanceResponse[ReheatParameters],
    responses={
        200: {"description": "Instance parameters retrieved"},
        404: {"description": "Instance not found", "model": ErrorResponse},
    },
)

@router.put(
    "/instances/{instance_id}",
    response_model=UpdateInstanceResponse[ReheatParameters],
    responses={
        200: {"description": "Instance parameters updated"},
        404: {"description": "Instance not found", "model": ErrorResponse},
        422: {"description": "Validation error in request body"},
    },
)

@router.post(
    "/instances/{instance_id}/step",
    response_model=StepResponse,
    responses={
        200: {"description": "Step executed successfully"},
        404: {"description": "Instance not found", "model": ErrorResponse},
        422: {"description": "Validation error in inputs"},
        500: {"description": "FMU execution error", "model": ErrorResponse},
    },
)

@router.delete(
    "/instances/{instance_id}",
    response_model=DeleteInstanceResponse,
    responses={
        200: {"description": "Instance deleted (or already not found)"},
    },
)
